void Q(std::string& o, const std::string& v) { static const char h[]="0123456789abcdef"; o+='"'; for(unsigned char c:v) switch(c) { case '"':o+="\\\"";break; case '\\':o+="\\\\";break; case '\b':o+="\\b";break; case '\f':o+="\\f";break; case '\n':o+="\\n";break; case '\r':o+="\\r";break; case '\t':o+="\\t";break; default: if(c<32){o+="\\u00";o+=h[c>>4];o+=h[c&15];}else o+=static_cast<char>(c); } o+='"'; }
void T(std::string& o,const char* n,const std::string& v){o+=",\"";o+=n;o+="\":";Q(o,v);} template <typename V> void F(std::string& o,const char* n,V v){o+=",\"";o+=n;o+="\":";N(o,v);}
