bool Decode(const std::string& s,std::uint8_t* p,std::size_t n){if(s.size()!=n*2)return false;for(std::size_t i=0;i<n;++i){const char a=s[i*2],b=s[i*2+1];const int x=a>='0'&&a<='9'?a-'0':a>='a'&&a<='f'?a-'a'+10:a>='A'&&a<='F'?a-'A'+10:-1,y=b>='0'&&b<='9'?b-'0':b>='a'&&b<='f'?b-'a'+10:b>='A'&&b<='F'?b-'A'+10:-1;if(x<0||y<0)return false;p[i]=static_cast<std::uint8_t>((x<<4)|y);}return true;}
