std::string Sources(std::uint64_t seq,const std::vector<W9SourceEvent>& e){std::string o="{\"schema\":\"ese.debug.source-resolutions/v1\",\"sequence\":"+std::to_string(seq)+",\"events\":[";for(std::size_t i=0;i<e.size();++i){const W9SourceEvent& x=e[i];if(i)o+=',';o=""+o+"{\"sequence\":"+std::to_string(x.sequence)+",\"hostname_sha256\":";Q(o,x.hostname_sha256);T(o,"file_ed2k_hash",x.file_ed2k_hash);F(o,"port",x.port);T(o,"resolver_result",x.resolver_result);o+=",\"resolved\":{\"ipv4_count\":"+std::to_string(x.resolved_ipv4)+",\"ipv6_count\":"+std::to_string(x.resolved_ipv6)+",\"endpoint_set_sha256\":";Q(o,x.resolved_endpoint_set_sha256);o+="},\"materialized\":{\"ipv4_count\":"+std::to_string(x.materialized_ipv4)+",\"ipv6_count\":"+std::to_string(x.materialized_ipv6)+",\"endpoint_set_sha256\":";Q(o,x.materialized_endpoint_set_sha256);o+=",\"simultaneously_retained\":";o+=B(x.simultaneously_retained);o+="},\"candidates\":[";for(std::size_t j=0;j<x.candidates.size();++j){const W9SourceCandidate& c=x.candidates[j];if(j)o+=',';o+="{\"family\":";Q(o,c.family);T(o,"endpoint_sha256",c.endpoint_sha256);T(o,"outcome",c.outcome);T(o,"source_origin",c.source_origin);o+='}';}o+="]}";}return o+"]}";}
std::string Subs(bool ok,const std::string& m,const std::vector<W9Subscription>& s){std::string o="{\"ok\":";o+=B(ok);o+=",\"msg\":";Q(o,m);o+=",\"count\":"+std::to_string(s.size())+",\"subscriptions\":[";for(std::size_t i=0;i<s.size();++i){if(i)o+=',';o+="{\"pubkey\":";Q(o,Hex(s[i].pubkey.data(),32));T(o,"name",s[i].name);F(o,"added",s[i].added);o+='}';}return o+"]}";}
std::string Diagnose(bool provided,bool valid,const W9DiagnoseSnapshot& s){std::string e="null";if(s.in_directory){e="{\"title\":";Q(e,s.entry.title);T(e,"ip",s.entry.broadcaster_ip);F(e,"port",s.entry.broadcaster_port);F(e,"bitrate",s.entry.bitrate);F(e,"viewerCount",s.entry.viewers);F(e,"lastSeenAgeMs",s.entry.last_seen_age_ms);e+=",\"isOwn\":";e+=B(s.entry.own);e+='}';}const char* hint=!s.kad_connected?"Kad is not connected. Wait or check firewall.":valid&&!s.in_directory?"Stream not in local directory. Run JoinStream first or wait for Kad propagation.":s.broadcasting&&!s.public_ip_available?"Broadcasting but no public IP detected. Check UPnP / port forward.":"OK";std::string o="{\"keyProvided\":";o+=B(provided);o+=",\"keyValid\":";o+=B(valid);o+=",\"kadConnected\":";o+=B(s.kad_connected);T(o,"publicIP",s.public_ip);F(o,"tcpPort",s.tcp_port);o+=",\"isBroadcasting\":";o+=B(s.broadcasting);o+=",\"isViewing\":";o+=B(s.viewing);F(o,"directorySize",s.directory_size);o+=",\"streamInDirectory\":";o+=B(s.in_directory);o+=",\"directoryEntry\":"+e+",\"hint\":";Q(o,hint);return o+'}';}
