bool RunW9LiveSearchApi(const W9SearchRequest& r,const W9SearchPort& p,W9SearchResponse& z){
	if(r.operation==W9SearchOperation::SourceResolutions){if(!r.loopback){z.body="{\"error\":\"forbidden\",\"hint\":\"this diagnostic is localhost-only\"}";z.header="HTTP/1.1 403 Forbidden\r\nContent-Type: application/json\r\nCache-Control: no-store\r\nContent-Length: "+std::to_string(z.body.size())+"\r\n\r\n";return true;}std::uint64_t n=0;std::vector<W9SourceEvent> e;if(p.read_source_events)p.read_source_events(p.context,LegacyUInt(r.after),n,e);z.body=Sources(n,e);z.header=H(z.body,"Content-Type: application/json\r\nCache-Control: no-store\r\nAccess-Control-Allow-Origin: http://127.0.0.1\r\nX-Content-Type-Options: nosniff\r\n");return true;}
	if(r.operation==W9SearchOperation::PrivacySubscriptions){bool ok=true;std::string m="ok";std::vector<W9Subscription>s;try{std::array<std::uint8_t,32>k{};if(!r.add.empty()){if(!Decode(r.add,k.data(),32)){ok=false;m="invalid pubkey hex (need 64 chars)";}else if(!p.add_subscription||!p.add_subscription(p.context,k,r.name,m)){ok=false;m="add failed (already subscribed?)";}}if(!r.remove.empty()){if(!Decode(r.remove,k.data(),32)){ok=false;m="invalid pubkey hex";}else if(!p.remove_subscription||!p.remove_subscription(p.context,k,m)){ok=false;m="not subscribed";}}if(!p.list_subscriptions||!p.list_subscriptions(p.context,s))throw std::runtime_error("list");z.body=Subs(ok,m,s);}catch(...){z.body="{\"ok\":false,\"msg\":\"exception in subscriptions handler\"}";}z.header=Legacy(z.body);return true;}
	if(r.operation==W9SearchOperation::TunnelSearch){std::string k=r.keyword,reply; if(k.empty())k="eselive";else if(!r.keyword_lowered)std::transform(k.begin(),k.end(),k.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));});bool ok=false;try{ok=p.tunnel_search&&p.tunnel_search(p.context,k,reply,12000);}catch(...){ }if(ok){z.body="{\"ok\":true,\"privacy\":\"DISCOVERY_ONLY\",\"originator_hidden_from_dht\":true,\"exit_sees_keyword\":true,\"keyword\":";Q(z.body,k);z.body+=",\"results\":"+reply+"}";}else z.body="{\"ok\":false,\"privacy\":\"DISCOVERY_ONLY\",\"reason\":\"no active circuit or timeout - build a circuit first via test_circuit\"}";z.header=Legacy(z.body);return true;}
	if(r.operation==W9SearchOperation::Diagnose){std::array<std::uint8_t,16> k{};const bool valid=r.key.size()==32&&Decode(r.key,k.data(),16);W9DiagnoseSnapshot s;if(p.read_diagnose)p.read_diagnose(p.context,valid?&k:nullptr,s);z.body=Diagnose(!r.key.empty(),valid,s);z.header=H(z.body,"Content-Type: application/json\r\nCache-Control: no-store\r\nAccess-Control-Allow-Origin: *\r\n");return true;}
	bool kad=false;std::vector<W9KadStream>s;if(p.request_kad_refresh)p.request_kad_refresh(p.context);if(p.read_kad_streams)p.read_kad_streams(p.context,kad,s);z.body=Streams(p,kad,s);z.header=H(z.body,"Content-Type: application/json\r\nAccess-Control-Allow-Origin: http://127.0.0.1\r\nX-Content-Type-Options: nosniff\r\n");return true;
}

