	struct S{unsigned adds=0,removes=0,refreshes=0,ticks=9;};S s;W9SearchPort p;W9SearchResponse r;p.context=&s;p.now_ms=[](void*x){return ++static_cast<S*>(x)->ticks;};p.read_source_events=[](void*,std::uint64_t a,std::uint64_t& n,std::vector<W9SourceEvent>& e){n=a+1;W9SourceEvent x;x.sequence=n;x.hostname_sha256="host";x.candidates.push_back({"v4","endpoint","kept","dns"});e.push_back(x);return true;};W9SearchRequest q;q.operation=W9SearchOperation::SourceResolutions;RunW9LiveSearchApi(q,p,r);if(r.body.find("forbidden")==std::string::npos){f="source loopback";return false;}q.loopback=true;q.after=" +7tail";RunW9LiveSearchApi(q,p,r);if(r.body.find("\"sequence\":8") == std::string::npos||r.body.find("hostname\"")!=std::string::npos){f="source wire";return false;}q.after="18446744073709551616";RunW9LiveSearchApi(q,p,r);if(r.body.find("\"sequence\":0") == std::string::npos){f="source overflow";return false;}
