	p.request_kad_refresh=[](void*x){++static_cast<S*>(x)->refreshes;};p.read_kad_streams=[](void*,bool&k,std::vector<W9KadStream>&v){k=true;W9KadStream a;a.key[0]=1;a.title="\n";a.last_seen=4;a.kad6_tunnel=true;v.push_back(a);return true;};q={};q.operation=W9SearchOperation::KadStreams;RunW9LiveSearchApi(q,p,r);if(s.refreshes!=1||s.ticks!=10||r.body.find("\"lastSeenAgeMs\":6")==std::string::npos||r.body.find("kad6_tunnel")==std::string::npos){f="kad streams";return false;}f.clear();return true;
